    switch (this) {
      case BusType.redOrdinary:
        return 'Red Ordinary';
      case BusType.blueExpress:
        return 'Blue Express';
      case BusType.greenCity:
        return 'Green City';
      case BusType.ultraDeluxe:
        return 'Ultra Deluxe';
      case BusType.metroExpress:
        return 'Metro Express';
    }
  }

  String get labelTelugu {
    switch (this) {
      case BusType.redOrdinary:
        return 'ఎర్ర సాధారణ';
